sys_variable_value.value:
(function execute(inputs, outputs) {
  var ADMIN_ROLE = 'x_1834930_office_0.office admin';

  outputs.is_admin = false;

  try {
    var createdBy = (inputs.created_by || '').toString().trim();
    if (!createdBy)
      return;

    var userSysId = '';
    var usr = new GlideRecord('sys_user');

    if (usr.get(createdBy)) {
      userSysId = usr.getUniqueValue();
    } else {
      usr.initialize();
      usr.addQuery('user_name', createdBy);
      usr.setLimit(1);
      usr.query();
      if (usr.next())
        userSysId = usr.getUniqueValue();
    }

    if (!userSysId)
      return;

    var has = new GlideRecord('sys_user_has_role');
    has.addQuery('user', userSysId);
    has.addQuery('role.name', ADMIN_ROLE);
    has.setLimit(1);
    has.query();

    outputs.is_admin = has.hasNext();
  } catch (e) {
    outputs.is_admin = false;
  }
})(inputs, outputs);

